CREATE OR REPLACE PACKAGE hr.staffing AS
  TYPE t_employee IS RECORD (
    id NUMBER,
    name VARCHAR2(4000),
    email VARCHAR2(4000),
    grade NUMBER
  );
  FUNCTION find_employee(p_id IN NUMBER) RETURN t_employee;
  PROCEDURE promote(p_id IN NUMBER);
END staffing;
/

CREATE OR REPLACE PACKAGE BODY hr.staffing AS

  FUNCTION find_employee(p_id IN NUMBER) RETURN t_employee IS
    l_row t_employee;
  BEGIN
    BEGIN
      select id, name, email, grade
      INTO l_row
      FROM employees where id = p_id;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        pell_runtime.set_err('hr_staffing_notfound:1', '{}');
        RAISE pell_runtime.hr_staffing_notfound;
      WHEN TOO_MANY_ROWS THEN RAISE;
    END;
    RETURN l_row;
  END find_employee;

  PROCEDURE promote(p_id IN NUMBER) IS
    l_e t_employee;
  BEGIN
    l_e := find_employee(p_id);
    IF (l_e.grade >= 9) THEN
      pell_runtime.set_err('hr_staffing_policyviolation:1', JSON_OBJECT('reason' VALUE 'already at max grade'));
      RAISE pell_runtime.hr_staffing_policyviolation;
    END IF;
    update employees set grade = grade + 1 where id = p_id;
    RETURN;
  END promote;
END staffing;
/